   assert(A.size() == X.size());
   assert(M * K == A.size());
   assert(K * N == X.size());
   assert(M * N == Y.size());

   std::vector<double> A_values(A.size());
   std::vector<size_t> A_rows(A.size());
   std::vector<size_t> A_columns(A.size());
   std::vector<double> X_values(X.size());
   std::vector<size_t> X_rows(X.size());
   std::vector<size_t> X_columns(X.size());
   std::vector<double> Y_values(Y.size());

   std::transform(A.begin(), A.end(), A_values.begin(), [](const auto& a) { return a.value; });
   std::transform(A.begin(), A.end(), A_rows.begin(), [](const auto& a) { return a.row; });
   std::transform(A.begin(), A.end(), A_columns.begin(), [](const auto& a) { return a.column; });
   std::transform(X.begin(), X.end(), X_values.begin(), [](const auto& x) { return x.value; });
   std::transform(X.begin(), X.end(), X_rows.begin(), [](const auto& x) { return x.row; });
   std::transform(X.begin(), X.end(), X_columns.begin(), [](const auto& x) { return x.column; });
   std::transform(Y.begin(), Y.end(), Y_values.begin(), [](const auto& y) { return y; });

   for (size_t i = 0; i < A.size(); ++i) {
