void convolveKernel(std::vector<int> const& imageIn, std::vector<int> &imageOut, size_t N) {
    for (size_t i = 0; i < N; i++) {
        for (size_t j = 0; j < N; j++){
            int sum = 0;
            for (int k = -1; k < 2; k++) {
                for (int l = -1; l < 2; l++){
                    int x = i + k;
                    int y = j + l;
                    if ((x < 0) || (x >= N) || (y < 0) || (y >= N)) {
